import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadPlanningPages } from '../src/pages/work/planning-data.js';
import { moveBody } from '../src/pages/work/board-state.js';
test('planning selectors collect every opaque cursor page and preserve list metadata', async () => {
  const paths = [];
  const api = { async get(path) { paths.push(path); return paths.length === 1 ? { items: [{ id: 'a' }], nextCursor: 'opaque+cursor', maxUploadBytes: 99 } : { items: [{ id: 'b' }], nextCursor: null, maxUploadBytes: 99 }; } };
  const result = await loadPlanningPages(api, '/issues/i/attachments?labelId=label');
  assert.deepEqual(result.items.map(item => item.id), ['a', 'b']); assert.equal(result.maxUploadBytes, 99);
  assert(paths[1].includes('cursor=opaque%2Bcursor')); assert(paths[1].includes('labelId=label'));
});
test('planning pagination refuses malformed or repeated server cursors', async () => {
  await assert.rejects(() => loadPlanningPages({ get: async () => ({ items: [], nextCursor: 'repeat' }) }, '/projects'), /repeated/);
  await assert.rejects(() => loadPlanningPages({ get: async () => ({ items: null }) }, '/projects'), /invalid/);
});
test('keyboard within-column move preserves its after anchor', () => {
  assert.deepEqual(moveBody({ statusId: 's', afterId: 'b' }, 'a'), { statusId: 's', afterId: 'b' });
});
